select order_id, cast( round( case when tax_start_month = report_month then ( opening_balance + opening_adjustment + purchase_amount - refund_amount + material_fee ) * coalesce(tax_rate, 0) / ( 1 + coalesce(tax_rate, 0) ) when tax_start_month < report_month then ( opening_adjustment + purchase_amount - refund_amount + material_fee ) * coalesce(tax_rate, 0) / ( 1 + coalesce(tax_rate, 0) ) else 0 end, 5 ) as decimal(38, 5) ) as tax_payable from style_lab.complex_case_source;
